69	    }
70	
71	    /**
72	     * The owner's membership points (see {@link MembershipLevel#points(Owner, Integer)} for the rule).
73	     *
74	     * <p>The household size is not derived here: it depends on other owners, so it is computed by
75	     * {@link org.springframework.samples.petclinic.rest.function.owner.OwnerHousehold} before the
76	     * owner reaches this mapper and read from the entity, keeping this a pure transformation.
77	     */
78	    default int membershipPoints(Owner owner) {
