80	    }
81	
82	    /**
83	     * The owner's raw numeric membership level, mapped from {@link #membershipPoints(Owner)}: level 1
84	     * for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more. This is the level before the
85	     * household ceiling in {@link #membershipLevel(Owner)} is applied.
86	     */
